/** Localises descriptive geography while preserving proper appellation names. */
export function geographicName(name:string,locale:Locale){
  if(locale==='en')return name
  const exact=geographicNames[locale][name]
  if(exact)return exact
  let value=name
  for(const [source,target] of Object.entries(geographyParts[locale]))value=value.replace(new RegExp(`\\b${source}\\b`,'g'),target)
  return value
}
export function regionName(region:Region|string,locale:Locale){
  const name=typeof region==='string'?region:region.name
  if(locale==='en')return name
  if(typeof region!=='string'){
    const translation=catalogTranslation('region',region.id,locale)
    const translated=translatedField(translation,'name')
    if(translated)return translated
  }
  return regionNames[locale][name]??geographicName(name,locale)
}

