function grapeOriginLabel(origin:string,locale:Locale){
  if(locale==='en')return origin
  if(fullOriginPhrases[locale][origin])return fullOriginPhrases[locale][origin]
  let value=origin
  for(const [source,target] of Object.entries(originPhrases[locale]).sort((a,b)=>b[0].length-a[0].length))value=value.replaceAll(source,target)
  for(const [source,target] of Object.entries(countryNames[locale]).sort((a,b)=>b[0].length-a[0].length))value=value.replaceAll(source,target)
  return value
}

