function list(values:string[],locale:Locale){const conjunction={en:' and ',de:' und ',fr:' et ',es:' y '}[locale];return values.length<2?values[0]??'':`${values.slice(0,-1).join(', ')}${conjunction}${values.at(-1)}`}
function extractTerms(source:string,terms:readonly (readonly [string,string,string,string,string])[],locale:Locale){const index={en:1,de:2,fr:3,es:4}[locale];return terms.filter(([pattern])=>new RegExp(pattern,'i').test(source)).map(term=>term[index]).slice(0,5)}

type ClimateProfile='maritime'|'mediterranean'|'continental'|'altitude'|'arid'|'cool'|'warm'|'mixed'
function climateProfile(source:string):ClimateProfile{const text=source.toLowerCase();if(/maritime|atlantic|ocean|fog|coast/.test(text))return'maritime';if(/mediterranean/.test(text))return'mediterranean';if(/continental/.test(text))return'continental';if(/altitude|elevated|mountain|high-altitude/.test(text))return'altitude';if(/arid|dry|desert/.test(text))return'arid';if(/cool|cold/.test(text))return'cool';if(/warm|hot/.test(text))return'warm';return'mixed'}
function soilProfile(source:string){const text=source.toLowerCase();if(/volcan|lava|basalt/.test(text))return'volcanic';if(/slate|schist|schiefer/.test(text))return'fractured';if(/limestone|chalk|calcareous|marl/.test(text))return'calcareous';if(/clay/.test(text))return'clay';if(/gravel|sand|alluvial/.test(text))return'draining';if(/granite|sandstone/.test(text))return'weathered';return'mixed'}

